settings.custom_css:
selector { --n-accordion-title-hover-color: #FD9ED0; --n-accordion-title-active-color: #FD9ED0; --n-accordion-title-justify-content: space-between; --n-accordion-title-flex-grow: 1; --n-accordion-title-icon-order: initial; --n-accordion-border-radius: 0px 0px 0px 0px; --n-accordion-padding: 20px 0px 20px 0px; }
selector .e-n-accordion-item-title-text { color: #FD9ED0 !important; font-size: 20px; font-weight: 400; line-height: 1.33em; flex: 1 1 auto; }
selector .e-n-accordion-item-title-icon { color: #FD9ED0 !important; order: 0 !important; margin-left: auto; }
selector .e-n-accordion-item-title-header { order: 0 !important; flex: 1 1 auto; }
selector .e-n-accordion-item-title-icon svg { fill: #FD9ED0 !important; }
selector > .e-n-accordion > .e-n-accordion-item > .e-n-accordion-item-title { border-style: solid; border-width: 0px 0px 1px 0px; border-color: #D5D8DC; padding: 20px 0px; }
selector > .e-n-accordion > .e-n-accordion-item[open] > .e-n-accordion-item-title { border-style: none; }
selector .e-n-accordion-item .e-con { padding: 0px 0px 20px 0px; }
selector .elementor-widget-text-editor p { color: #333333; font-size: 15px; font-weight: 400; line-height: 1.42em; font-family: Inter, sans-serif; }
